 — قافلة الإبداعية | قافلة الإبداعية', 'Executive guide by Qafila Creative covering Complete Brand Identity System benchmarks in Bahrain.', 'دليل تنفيذي من قافلة الإبداعية حول معايير تصميم نظام الهوية البصرية الكامل في البحرين.', 'Insights', '{"agency","insights","Seef District","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Qafila Creative initiate a Complete Brand Identity System engagement?', 'كم يستغرق بدء تنفيذ خدمة تصميم نظام الهوية البصرية الكامل لدى قافلة الإبداعية؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Seef District.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Seef District.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
