INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'qafila-creative-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Qafila Creative in Seef District.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من قافلة الإبداعية في Seef District.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Independent brand and digital agency partnering with ambitious regional enterprises on strategy, design systems, and launch campaigns. Focusing on Trade Pavilion & Experiential Booth Design, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"وكالة مستقلة للعلامات التجارية والتجربة الرقمية تتعاون مع المؤسسات الطموحة في الاستراتيجية والتصميم والحملات. من خلال خدمة تصميم الأجنحة التفاعلية والمعارض نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Independent brand and digital agency partnering with ambitious regional enterprises on strategy, design systems, and launch campaigns.</p><p>Focusing on <strong>Trade Pavilion & Experiential Booth Design</strong>, our Seef District specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>وكالة مستقلة للعلامات التجارية والتجربة الرقمية تتعاون مع المؤسسات الطموحة في الاستراتيجية والتصميم والحملات.</p><p>من خلال خدمة <strong>تصميم الأجنحة التفاعلية والمعارض</strong>، يعمل فريقنا في Seef District على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Qafila Creative', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | قافلة الإبداعية', 'Executive guide by Qafila Creative covering Trade Pavilion & Experiential Booth Design benchmarks in Bahrain.', 'دليل تنفيذي من قافلة الإبداعية حول معايير تصميم الأجنحة التفاعلية والمعارض في البحرين.', 'Sustainability', '{"agency","sustainability","Seef District","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
